import club.heiqi.uilib.ui.scene.text.TextStyle;

/** 真GPU读取RGBA：图像/文字/rect有序批次、fit与有效clip、upload预算和状态恢复，不伪物品render。 */
public final class ImageGlScenario extends TestApplication {
    private static final int W=380,H=170;private ClientFontServices fonts;private GlImageResources images;private GlPaintPlanRenderer renderer;private int[] pixels;private File output;private boolean glyphsReady;
    private static ImageContent solid(int width,int height,int rgba){byte[] values=new byte[width*height*4];for(int i=0;i<values.length;i+=4){values[i]=(byte)(rgba>>>24);values[i+1]=(byte)(rgba>>>16);values[i+2]=(byte)(rgba>>>8);values[i+3]=(byte)rgba;}return new ImageContent(width,height,values);}
    private static ImageContent stripes(){byte[] rgba=new byte[120*60*4];for(int y=0;y<60;y++)for(int x=0;x<120;x++){int i=(y*120+x)*4;rgba[i+x/40]=(byte)255;rgba[i+3]=(byte)255;}return new ImageContent(120,60,rgba);}
    private PaintCommand image(ImageContent content,LayoutBox box,ImageOptions.Fit fit,LayoutBox clip){return PaintCommand.image(box,clip,ImagePlacement.fit(content,box,ImageOptions.defaults().fit(fit)));}
    private static void clear(){glDisable(GL_SCISSOR_TEST);glClearColor(1,1,1,1);glClear(GL_COLOR_BUFFER_BIT);}
    private void capture()throws Exception{ByteBuffer buffer=MemoryUtil.memAlloc(W*H*4);try{glReadPixels(0,0,W,H,GL_RGBA,GL_UNSIGNED_BYTE,buffer);pixels=new int[W*H];for(int y=0;y<H;y++)for(int x=0;x<W;x++){int i=((H-y-1)*W+x)*4;pixels[y*W+x]=((buffer.get(i+3)&255)<<24)|((buffer.get(i)&255)<<16)|((buffer.get(i+1)&255)<<8)|(buffer.get(i+2)&255);}}finally{MemoryUtil.memFree(buffer);}}
    private void color(int x,int y,int expected){int value=pixels[y*W+x];for(int shift:new int[]{0,8,16,24})require(Math.abs(((value>>>shift)&255)-((expected>>>shift)&255))<=2,"像素("+x+","+y+")实际="+Integer.toHexString(value)+"期望="+Integer.toHexString(expected));}
    private void render(PaintPlan plan)throws Exception{try(GlPaintPlanRenderer.Prepared prepared=fonts.prepare(renderer,plan,new LayoutBox(0,0,W,H))){prepared.render(FramebufferCoordinates.orthographic(W,H),H,false);glyphsReady=prepared.readyCount()==prepared.demandCount();}capture();}
    private void save(String name)throws Exception{BufferedImage image=new BufferedImage(W,H,BufferedImage.TYPE_INT_ARGB);image.setRGB(0,0,W,H,pixels,0,W);ImageIO.write(image,"png",new File(output,name));}
    @Override protected void setup()throws Exception{output=new File(arguments().length==0?"build/image-system/gpu":arguments()[0]);require(output.isDirectory()||output.mkdirs(),"GPU输出目录失败");GlfwTestEnvironment environment=own(new GlfwTestEnvironment());environment.window(W,H,"UILib image GPU",GlfwTestEnvironment.Profile.CORE,2);Lwjgl3GlApi gl=new Lwjgl3GlApi();fonts=own(new ClientFontServices(getClass().getClassLoader(),1,ClientFontServices.Settings.defaults(),IsolatedFontEngine.shared(),gl,GlProgramProvider.NONE));images=own(new GlImageResources(gl,16,1024*1024));renderer=fonts.createPlanRenderer(images);onClose(()->fonts.releasePlanRenderer(renderer));
        int texture=glGenTextures(),fbo=glGenFramebuffers();onClose(()->{glBindFramebuffer(GL_FRAMEBUFFER,0);glDeleteFramebuffers(fbo);glDeleteTextures(texture);});glBindTexture(GL_TEXTURE_2D,texture);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,W,H,0,GL_RGBA,GL_UNSIGNED_BYTE,(ByteBuffer)null);glBindFramebuffer(GL_FRAMEBUFFER,fbo);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,texture,0);require(glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE,"FBO失败");glViewport(0,0,W,H);System.out.println("vendor="+glGetString(GL_VENDOR)+" renderer="+glGetString(GL_RENDERER)+" version="+glGetString(GL_VERSION));}
    @Override protected void runTests()throws Exception {
        scenario("真实contain cover stretch native及ancestorclip",()->{ImageContent red=stripes();PaintPlanBuilder builder=new PaintPlanBuilder();int index=0;for(ImageOptions.Fit fit:ImageOptions.Fit.values()){LayoutBox box=new LayoutBox(10+index++*90,20,80,80);LayoutBox clip=fit==ImageOptions.Fit.COVER||fit==ImageOptions.Fit.NATIVE?box:null;builder.add(image(red,box,fit,clip));}clear();render(builder.build());color(15,25,0xFFFFFFFF);color(15,50,0xFFFF0000);color(105,25,0xFFFF0000);color(95,25,0xFFFFFFFF);color(195,25,0xFFFF0000);color(285,25,0xFFFFFFFF);color(285,50,0xFFFF0000);color(275,50,0xFFFFFFFF);color(31,60,0xFFFF0000);color(121,60,0xFF00FF00);color(211,60,0xFFFF0000);color(301,60,0xFF00FF00);save("fits.png");});
        scenario("straightRGBA透明与rect image text原序后续文字state",()->{ImageContent transparent=solid(2,2,0xFF000080);TextLayout text=fonts.layout("Image 后的中文 Text",new TextStyle("default",18,0xFF101010),340);PaintPlanBuilder builder=new PaintPlanBuilder();builder.add(PaintCommand.rect(new LayoutBox(10,10,80,80),null,0xFF0000FF));builder.add(image(transparent,new LayoutBox(10,10,80,80),ImageOptions.Fit.STRETCH,null));builder.add(PaintCommand.rect(new LayoutBox(30,30,20,20),null,0xFF00FF00));builder.add(PaintCommand.text(new LayoutBox(10,110,340,40),null,text));PaintPlan plan=builder.build();for(int i=0;i<80;i++){clear();render(plan);if(glyphsReady&&fonts.rasterizer().stats().started)break;Thread.sleep(5);}color(20,20,0xFF80007F);color(40,40,0xFF00FF00);int dark=0;for(int y=110;y<155;y++)for(int x=10;x<350;x++)if((pixels[y*W+x]&0xFFFFFF)<0x606060)dark++;require(dark>30,"图像后文字未产生真实glyph像素");save("alpha-order-text.png");});
        scenario("图像上传pixelstore PBO texture与后续quad恢复",()->{int oldUnit=glGetInteger(GL_ACTIVE_TEXTURE);glActiveTexture(GL_TEXTURE0+3);int texture=glGenTextures(),pbo=glGenBuffers();onClose(()->{glBindBuffer(GL_PIXEL_UNPACK_BUFFER,0);glDeleteBuffers(pbo);glDeleteTextures(texture);glActiveTexture(oldUnit);});glBindTexture(GL_TEXTURE_2D,texture);glBindBuffer(GL_PIXEL_UNPACK_BUFFER,pbo);glBufferData(GL_PIXEL_UNPACK_BUFFER,4096,GL_STATIC_DRAW);glPixelStorei(GL_UNPACK_ALIGNMENT,8);glPixelStorei(GL_UNPACK_ROW_LENGTH,7);glPixelStorei(GL_UNPACK_SKIP_ROWS,2);glEnable(GL_SCISSOR_TEST);glScissor(2,3,20,21);glEnable(GL_BLEND);glBlendFuncSeparate(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA,GL_ONE,GL_ZERO);int[] scissor=new int[4];glGetIntegerv(GL_SCISSOR_BOX,scissor);PaintPlanBuilder builder=new PaintPlanBuilder();builder.add(image(solid(3,3,0x00FF00FF),new LayoutBox(5,5,15,15),ImageOptions.Fit.STRETCH,null));render(builder.build());require(glGetInteger(GL_ACTIVE_TEXTURE)==GL_TEXTURE0+3&&glGetInteger(GL_TEXTURE_BINDING_2D)==texture,"图像破坏宿主纹理绑定");require(glGetInteger(GL_PIXEL_UNPACK_BUFFER_BINDING)==pbo&&glGetInteger(GL_UNPACK_ALIGNMENT)==8&&glGetInteger(GL_UNPACK_ROW_LENGTH)==7&&glGetInteger(GL_UNPACK_SKIP_ROWS)==2,"图像上传污染PBO/pixelstore");int[] restored=new int[4];glGetIntegerv(GL_SCISSOR_BOX,restored);require(Arrays.equals(scissor,restored)&&glIsEnabled(GL_SCISSOR_TEST)&&glGetInteger(GL_BLEND_SRC_RGB)==GL_SRC_ALPHA,"图像quad污染scissor/blend");glBindBuffer(GL_PIXEL_UNPACK_BUFFER,0);glPixelStorei(GL_UNPACK_ALIGNMENT,4);glPixelStorei(GL_UNPACK_ROW_LENGTH,0);glPixelStorei(GL_UNPACK_SKIP_ROWS,0);glDisable(GL_SCISSOR_TEST);});
        scenario("GPU局部失败与每次upload预算后续rect继续",()->{final int[] failure={0},pending={0};GlImageResources tiny=own(new GlImageResources(new Lwjgl3GlApi(),4,64,4,1,(identity,waiting,message)->{if(message!=null)failure[0]++;if(waiting)pending[0]++;}));GlPaintPlanRenderer consumer=fonts.createPlanRenderer(tiny);onClose(()->fonts.releasePlanRenderer(consumer));ImageContent tooLarge=solid(2,2,0x00FF00FF),a=solid(1,1,0xFF0000FF),b=solid(1,1,0x0000FFFF);PaintPlanBuilder builder=new PaintPlanBuilder();builder.add(image(tooLarge,new LayoutBox(10,10,20,20),ImageOptions.Fit.STRETCH,null));builder.add(image(a,new LayoutBox(40,10,20,20),ImageOptions.Fit.STRETCH,null));builder.add(image(b,new LayoutBox(70,10,20,20),ImageOptions.Fit.STRETCH,null));builder.add(PaintCommand.rect(new LayoutBox(100,10,20,20),null,0xFF00FF00));PaintPlan plan=builder.build();clear();try(GlPaintPlanRenderer.Prepared prepared=fonts.prepare(consumer,plan,new LayoutBox(0,0,W,H))){prepared.render(FramebufferCoordinates.orthographic(W,H),H,false);}capture();color(15,15,0xFF642D35);color(45,15,0xFFFF0000);color(75,15,0xFF39434F);color(105,15,0xFF00FF00);require(failure[0]==1&&pending[0]==1,"上传失败/限额缺局部反馈");clear();try(GlPaintPlanRenderer.Prepared prepared=fonts.prepare(consumer,plan,new LayoutBox(0,0,W,H))){prepared.render(FramebufferCoordinates.orthographic(W,H),H,false);}capture();color(75,15,0xFF0000FF);save("upload-budget-failure.png");});
        scenario("HOST_ITEM缺adapterUnsupported与hostthrow局部failed后rect继续",()->{
            final String[] stage={""};final boolean[] unsupported={false};
            try(GlImageResources resources=new GlImageResources(new Lwjgl3GlApi(),2,1024,1024,2,new GlImageResources.Listener(){public void presentation(long identity,boolean pending,String failure){}public void failure(long identity,String value,boolean missing,String diagnostic){stage[0]=value;unsupported[0]=missing;}})){
                ImageContent host=new ImageContent(16,16){};PaintPlanBuilder b=new PaintPlanBuilder();b.add(image(host,new LayoutBox(10,10,40,40),ImageOptions.Fit.STRETCH,null));b.add(PaintCommand.rect(new LayoutBox(60,10,30,30),null,0xff00ff00));GlPaintPlanRenderer delegate=fonts.createPlanRenderer(resources);
                try{clear();try(GlPaintPlanRenderer.Prepared prepared=fonts.prepare(delegate,b.build(),new LayoutBox(0,0,W,H))){prepared.render(FramebufferCoordinates.orthographic(W,H),H,false);}capture();color(15,15,0xff642d35);color(65,15,0xff00ff00);require(unsupported[0]&&stage[0].equals("item-adapter"),"缺host adapter未明确unsupported");
                    resources.hostItems(new GlImageResources.HostItems(){public boolean supports(ImageContent content){return content==host;}public void render(club.heiqi.uilib.ui.scene.image.ImagePlacement p,LayoutBox c,int w,int h){throw new IllegalStateException("host render failed");}});clear();try(GlPaintPlanRenderer.Prepared prepared=fonts.prepare(delegate,b.build(),new LayoutBox(0,0,W,H))){prepared.render(FramebufferCoordinates.orthographic(W,H),H,false);}capture();color(15,15,0xff642d35);color(65,15,0xff00ff00);require(!unsupported[0]&&stage[0].equals("item-render"),"host失败未局部failed stage");
                }finally{fonts.releasePlanRenderer(delegate);}
            }
        });
        scenario("正式字体owner delegate连续consumer不污染冻结父Frame",()->{TextLayout text=fonts.layout("Parent W 后续",new TextStyle("default",18,0xff101010),W);PaintPlanBuilder b=new PaintPlanBuilder();b.add(PaintCommand.text(new LayoutBox(10,100,300,50),null,text));PaintPlan plan=b.build();for(int i=0;i<100;i++){clear();render(plan);if(glyphsReady)break;Thread.sleep(5);}GlPaintPlanRenderer nested=fonts.createPlanRenderer();try{clear();try(GlPaintPlanRenderer.Prepared parent=fonts.prepare(renderer,plan,new LayoutBox(0,0,W,H));GlPaintPlanRenderer.Replay replay=parent.begin(FramebufferCoordinates.orthographic(W,H),H,false)){long resource=parent.resident(text.lines().get(0).glyphs().get(0)).resource;replay.delegate(()->fonts.withDelegatedConsumer(()->{for(int i=0;i<2;i++)try(GlPaintPlanRenderer.Prepared child=fonts.prepare(nested,plan,new LayoutBox(0,0,W,H))){child.render(FramebufferCoordinates.orthographic(W,H),H,false);}}));require(parent.resident(text.lines().get(0).glyphs().get(0)).resource==resource,"nested consumer修改父resident");for(PaintCommand command:plan.commands())replay.draw(command);}capture();int dark=0;for(int y=100;y<150;y++)for(int x=10;x<300;x++)if((pixels[y*W+x]&0xffffff)<0x606060)dark++;require(dark>20,"委托恢复后父文字缺失");}finally{fonts.releasePlanRenderer(nested);}});
        scenario("真实glyph父partial借用连续consumer容量与GPUpressure",()->borrowPressure());
        require(glGetError()==GL_NO_ERROR,"图像GPU场景留下GLerror");
    }
    private void borrowPressure()throws Exception{
        TextLayout large=fonts.layout("WMQ",new TextStyle("default",48,0xff101010),W),small=fonts.layout(".i",new TextStyle("default",8,0xff101010),W);
        java.util.List<club.heiqi.uilib.ui.scene.text.font.glyph.GlyphKey> big=new java.util.ArrayList<>(),little=new java.util.ArrayList<>();
        for(TextLayout.Line line:large.lines())for(TextLayout.Glyph glyph:line.glyphs())big.add(club.heiqi.uilib.ui.scene.text.font.glyph.GlyphKey.of(glyph));
        for(TextLayout.Line line:small.lines())for(TextLayout.Glyph glyph:line.glyphs())little.add(club.heiqi.uilib.ui.scene.text.font.glyph.GlyphKey.of(glyph));
        java.util.List<club.heiqi.uilib.ui.scene.text.font.glyph.GlyphKey> all=new java.util.ArrayList<>(big);all.addAll(little);for(club.heiqi.uilib.ui.scene.text.font.glyph.GlyphKey key:all)fonts.rasterizer().request(key);
        for(int i=0;i<100;i++){fonts.pumpReady();boolean ready=true;for(club.heiqi.uilib.ui.scene.text.font.glyph.GlyphKey key:all)ready&=fonts.rasterizer().peek(key)!=null;if(ready)break;Thread.sleep(5);}
        int page=4;for(club.heiqi.uilib.ui.scene.text.font.glyph.GlyphKey key:all){club.heiqi.uilib.ui.scene.text.font.nativefont.GlyphBitmap bitmap=fonts.rasterizer().peek(key);require(bitmap!=null,"真实压力glyph未完成");page=Math.max(page,Math.max(bitmap.width+2,bitmap.height+2));}
        club.heiqi.uilib.ui.scene.text.font.nativefont.GlyphBitmap parentBitmap=fonts.rasterizer().peek(big.get(0));long oneRow=4L*(parentBitmap.width+2);
        for(boolean capacity:new boolean[]{true,false}){
            java.util.List<club.heiqi.uilib.ui.scene.text.font.glyph.GlyphKey> children=capacity?little:big.subList(1,3);
            try(club.heiqi.uilib.host.client.gl.GlGlyphAtlas tiny=new club.heiqi.uilib.host.client.gl.GlGlyphAtlas(new Lwjgl3GlApi(),club.heiqi.uilib.host.client.gl.GlGlyphAtlas.Mode.TEXTURE_2D,new club.heiqi.uilib.host.client.gl.GlGlyphAtlas.Budget(page,1,capacity?2:1,capacity?1:3,8,2L*page*page*4))){
                try(club.heiqi.uilib.host.client.gl.GlGlyphAtlas.Frame parent=tiny.beginFrame(java.util.Collections.singletonList(big.get(0)))){parent.prepare(fonts.rasterizer(),new club.heiqi.uilib.host.client.gl.GlGlyphAtlas.UploadBudget(oneRow,1000000000,1));parent.freeze();require(parent.lookup(big.get(0))==null&&tiny.stats().uploadedBytes==oneRow,"父partial场景未命中分行上传");
                    tiny.borrowFrozenFrame(()->{for(club.heiqi.uilib.ui.scene.text.font.glyph.GlyphKey key:children)try(club.heiqi.uilib.host.client.gl.GlGlyphAtlas.Frame child=tiny.beginFrame(java.util.Collections.singletonList(key))){child.prepare(fonts.rasterizer(),new club.heiqi.uilib.host.client.gl.GlGlyphAtlas.UploadBudget(65536,1000000000,8));child.freeze();require(child.lookup(key)==null,"nested consumer突破父partial预算保护");}});
                    require(tiny.stats().evictedGroups==0&&tiny.stats().residents==0,"借用期间父partial被淘汰/容量突破");}
                try(club.heiqi.uilib.host.client.gl.GlGlyphAtlas.Frame resumed=tiny.beginFrame(java.util.Collections.singletonList(big.get(0)))){resumed.prepare(fonts.rasterizer(),new club.heiqi.uilib.host.client.gl.GlGlyphAtlas.UploadBudget(65536,1000000000,8));resumed.freeze();club.heiqi.uilib.host.client.gl.GlGlyphAtlas.Resident resident=resumed.lookup(big.get(0));require(resident!=null&&glIsTexture(tiny.resolve(resident.resource,resident.generation).id)&&tiny.stats().residents==1,"借用后父partial未完成/悬空texture");}
                System.out.println("borrowPressure capacity="+capacity+" realParent="+parentBitmap.width+"x"+parentBitmap.height+" page="+page+" rowBytes="+oneRow+" evicted="+tiny.stats().evictedGroups+" residents="+tiny.stats().residents+" rejected="+tiny.stats().rejected);
            }
        }
    }
    public static void main(String[] args)throws Exception{new ImageGlScenario().run(args);}
}
